def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    size = len(alphabet)
    char_index = {char: i for i, char in enumerate(alphabet)}
    transitions = [[-1] * size]
    failure = [0]
    forbidden = [False]

    for word in banned:
        state = 0
        for char in word:
            index = char_index[char]
            if transitions[state][index] == -1:
                transitions[state][index] = len(transitions)
                transitions.append([-1] * size)
                failure.append(0)
                forbidden.append(False)
            state = transitions[state][index]
        forbidden[state] = True

    from collections import deque

    queue = deque()
    for index in range(size):
        child = transitions[0][index]
        if child == -1:
            transitions[0][index] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        forbidden[state] |= forbidden[failure[state]]
        for index in range(size):
            child = transitions[state][index]
            if child == -1:
                transitions[state][index] = transitions[failure[state]][index]
            else:
                failure[child] = transitions[failure[state]][index]
                queue.append(child)

    states = [state for state in range(len(transitions)) if not forbidden[state]]
    state_index = {state: i for i, state in enumerate(states)}
    count = len(states)

    matrix = [[0] * count for _ in range(count)]
    for state in states:
        row = matrix[state_index[state]]
        for target in transitions[state]:
            if not forbidden[target]:
                row[state_index[target]] += 1

    vector = [0] * count
    vector[state_index[0]] = 1

    while n:
        if n & 1:
            result = [0] * count
            for i, value in enumerate(vector):
                if value:
                    row = matrix[i]
                    for j, entry in enumerate(row):
                        result[j] += value * entry
            vector = [value % MOD for value in result]

        n >>= 1
        if n:
            squared = [[0] * count for _ in range(count)]
            for i in range(count):
                result_row = squared[i]
                for k, value in enumerate(matrix[i]):
                    if value:
                        row = matrix[k]
                        for j, entry in enumerate(row):
                            result_row[j] += value * entry
                for j in range(count):
                    result_row[j] %= MOD
            matrix = squared

    return sum(vector) % MOD
